import{_ as l,o as a,c as d,ag as i}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"毛泽东文集（人民出版社版）完整总结","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/mao-zedong/mao-collected-works.md","filePath":"topics/mao-zedong/mao-collected-works.md"}'),r={name:"topics/mao-zedong/mao-collected-works.md"};function o(e,t,n,s,h,u){return a(),d("div",null,[...t[0]||(t[0]=[i(`<h1 id="毛泽东文集-人民出版社版-完整总结" tabindex="-1">毛泽东文集（人民出版社版）完整总结 <a class="header-anchor" href="#毛泽东文集-人民出版社版-完整总结" aria-label="Permalink to &quot;毛泽东文集（人民出版社版）完整总结&quot;">​</a></h1><blockquote><p>版本：人民出版社1993-1999年出版，共8卷 时间跨度：1921年-1949年 说明：本文集与《毛泽东选集》互为补充——选集精选最具代表性的名篇，文集则收录更多内部文章、指示、批示、电报等原始文献，范围更广、更原始。</p></blockquote><hr><h2 id="一、全8卷卷次结构" tabindex="-1">一、全8卷卷次结构 <a class="header-anchor" href="#一、全8卷卷次结构" aria-label="Permalink to &quot;一、全8卷卷次结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>卷次</th><th>时间段</th><th>副标题/定位</th></tr></thead><tbody><tr><td>第1卷</td><td>1921-1927</td><td>建党初期到大革命失败</td></tr><tr><td>第2卷</td><td>1928-1935</td><td>井冈山斗争到长征前夕</td></tr><tr><td>第3卷</td><td>1935-1938</td><td>遵义会议到抗战初期</td></tr><tr><td>第4卷</td><td>1938-1941</td><td>抗战相持阶段</td></tr><tr><td>第5卷</td><td>1941-1945</td><td>延安整风到大后方建设</td></tr><tr><td>第6卷</td><td>1945-1948</td><td>解放战争战略进攻阶段</td></tr><tr><td>第7卷</td><td>1948-1949</td><td>解放战争决战到建国前夕</td></tr><tr><td>第8卷</td><td>（部分版本含1949后）</td><td>建国初期</td></tr></tbody></table><hr><h2 id="二、按历史时期分卷详解" tabindex="-1">二、按历史时期分卷详解 <a class="header-anchor" href="#二、按历史时期分卷详解" aria-label="Permalink to &quot;二、按历史时期分卷详解&quot;">​</a></h2><h3 id="📖-第1卷-1921-1927-建党与大革命的狂飙" tabindex="-1">📖 第1卷（1921-1927）：建党与大革命的狂飙 <a class="header-anchor" href="#📖-第1卷-1921-1927-建党与大革命的狂飙" aria-label="Permalink to &quot;📖 第1卷（1921-1927）：建党与大革命的狂飙&quot;">​</a></h3><p><strong>时代背景</strong></p><ul><li>中国共产党成立（1921）</li><li>第一次国共合作（1924）</li><li>北伐战争（1926-1927）</li><li>大革命失败（1927年四一二/七一五）</li></ul><p><strong>核心文章</strong></p><table tabindex="0"><thead><tr><th>文章</th><th>年份</th><th>核心内容</th></tr></thead><tbody><tr><td>《给蔡元培的信》</td><td>1920</td><td>早期思想启蒙，马克思主义传播</td></tr><tr><td>《外力、军阀与革命》</td><td>1923</td><td>分析中国政治格局，提出革命策略</td></tr><tr><td>《中国社会各阶级的分析》</td><td>1925</td><td><strong>开篇之作</strong>。提出&quot;谁是我们的敌人，谁是我们的朋友，这个问题是革命的首要问题&quot;。系统分析地主、买办、中产、小资产、半无产、无产等阶级，为党制定统一战线政策奠基</td></tr><tr><td>《国民革命与农民运动》</td><td>1926</td><td>农民问题是革命的中心问题；&quot;农民问题乃国民革命的中心问题&quot;</td></tr><tr><td>《湖南农民运动考察报告》</td><td>1927.02</td><td><strong>成名之作</strong>。实地调研湖南农民运动，提出&quot;矫枉必须过正&quot;的经典论断。系统总结农民运动的十四件大事，成为党领导农民运动的纲领性文献</td></tr></tbody></table><p><strong>关键历史节点</strong></p><ul><li>1921年参加中共一大（建党）</li><li>1922年领导安源路矿工人大罢工（工运起点）</li><li>1925年回韶山开展农民运动</li><li>1927年八七会议提出&quot;枪杆子里面出政权&quot;</li></ul><hr><h3 id="📖-第2卷-1928-1935-井冈山与中央苏区" tabindex="-1">📖 第2卷（1928-1935）：井冈山与中央苏区 <a class="header-anchor" href="#📖-第2卷-1928-1935-井冈山与中央苏区" aria-label="Permalink to &quot;📖 第2卷（1928-1935）：井冈山与中央苏区&quot;">​</a></h3><p><strong>时代背景</strong></p><ul><li>井冈山根据地创建（1927-1929）</li><li>朱毛会师（1928.04）</li><li>中央苏区建立（1929-1934）</li><li>五次反&quot;围剿&quot;（1930-1934）</li><li>第五次反围剿失败，长征开始（1934.10）</li></ul><p><strong>核心文章</strong></p><table tabindex="0"><thead><tr><th>文章</th><th>年份</th><th>核心内容</th></tr></thead><tbody><tr><td>《中国的红色政权为什么能够存在？》</td><td>1928.10</td><td><strong>井冈山道路的理论奠基</strong>。分析白色政权间战争、小农经济、党的领导、军事力量等五条件，论证红色政权存在和发展的必然性</td></tr><tr><td>《井冈山的斗争》</td><td>1928.11</td><td>全面总结井冈山根据地经验，提出&quot;工农武装割据&quot;完整概念；建军原则（党指挥枪）和土地政策</td></tr><tr><td>《星星之火，可以燎原》</td><td>1930.01</td><td><strong>战略预见之作</strong>。批评&quot;流寇思想&quot;，提出&quot;以农村包围城市&quot;的战略构想，预言革命高潮即将到来</td></tr><tr><td>《反对本本主义》</td><td>1930.05</td><td><strong>思想路线奠基之作</strong>。首次提出&quot;没有调查，没有发言权&quot;；批判教条主义；奠定实事求是思想路线基础</td></tr><tr><td>《必须注意经济工作》</td><td>1933.08</td><td>在根据地建设中重视经济建设，发展国民经济，打破国民党经济封锁</td></tr><tr><td>《关心群众生活，注意工作方法》</td><td>1934.01</td><td><strong>群众路线经典</strong>。&quot;真正的铜墙铁壁是群众&quot;，把群众利益与革命战争紧密结合</td></tr></tbody></table><p><strong>关键历史节点</strong></p><ul><li>1927年领导秋收起义，上井冈山</li><li>1928年朱毛会师，成立红四军</li><li>1929年古田会议（毛泽东起草决议，提出党对军队的绝对领导）</li><li>1931年中华苏维埃共和国临时中央政府成立</li></ul><p><strong>理论贡献</strong></p><ul><li>农村包围城市道路的初步形成</li><li>&quot;工农武装割据&quot;思想</li><li>人民军队建设原则（党指挥枪）</li><li>土地革命路线</li></ul><hr><h3 id="📖-第3卷-1935-1938-遵义会议与全面抗战准备" tabindex="-1">📖 第3卷（1935-1938）：遵义会议与全面抗战准备 <a class="header-anchor" href="#📖-第3卷-1935-1938-遵义会议与全面抗战准备" aria-label="Permalink to &quot;📖 第3卷（1935-1938）：遵义会议与全面抗战准备&quot;">​</a></h3><p><strong>时代背景</strong></p><ul><li>长征（1934.10-1935.10）</li><li>遵义会议（1935.01），毛泽东进入领导核心</li><li>瓦窑堡会议（1935.12），建立抗日民族统一战线</li><li>西安事变和平解决（1936.12）</li><li>七七事变，全面抗战开始（1937.07）</li></ul><p><strong>核心文章</strong></p><table tabindex="0"><thead><tr><th>文章</th><th>年份</th><th>核心内容</th></tr></thead><tbody><tr><td>《论反对日本帝国主义的策略》</td><td>1935.12</td><td><strong>政治路线的根本转变</strong>。提出建立抗日民族统一战线的必要性和可能性；批判关门主义；将工农共和国改为人民共和国</td></tr><tr><td>《中国革命战争的战略问题》</td><td>1936.12</td><td><strong>军事理论奠基</strong>。系统总结中国革命战争的特点、规律、战略战术；提出&quot;战略上藐视敌人，战术上重视敌人&quot;</td></tr><tr><td>《实践论》</td><td>1937.07</td><td><strong>哲学名篇</strong>。知行关系论：实践是认识的基础；认识的两个阶段（感性→理性）；实践-认识-再实践的辩证法</td></tr><tr><td>《矛盾论》</td><td>1937.08</td><td><strong>哲学名篇</strong>。对立统一规律；矛盾的普遍性与特殊性；主要矛盾与次要矛盾；矛盾的主要方面与次要方面</td></tr></tbody></table><p><strong>关键历史节点</strong></p><ul><li>1935年遵义会议确立毛泽东领导地位</li><li>1936年促成西安事变和平解决</li><li>1937年洛川会议确定全面抗战路线</li></ul><p><strong>理论贡献</strong></p><ul><li>抗日民族统一战线理论</li><li>革命战争的战略战术体系</li><li>马克思主义认识论（中国化）</li><li>矛盾分析法（中国化）</li></ul><hr><h3 id="📖-第4卷-1938-1941-相持阶段的理论与实践" tabindex="-1">📖 第4卷（1938-1941）：相持阶段的理论与实践 <a class="header-anchor" href="#📖-第4卷-1938-1941-相持阶段的理论与实践" aria-label="Permalink to &quot;📖 第4卷（1938-1941）：相持阶段的理论与实践&quot;">​</a></h3><p><strong>时代背景</strong></p><ul><li>抗战进入相持阶段（1938.10后）</li><li>国民党消极抗日、积极反共</li><li>延安成为抗日根据地中心</li><li>皖南事变（1941.01）</li></ul><p><strong>核心文章</strong></p><table tabindex="0"><thead><tr><th>文章</th><th>年份</th><th>核心内容</th></tr></thead><tbody><tr><td>《论持久战》</td><td>1938.05</td><td><strong>战略预测巅峰之作</strong>。预判抗战三阶段（防御→相持→反攻）；驳斥&quot;速胜论&quot;和&quot;亡国论&quot;；强调人民战争和游击战</td></tr><tr><td>《战争和战略问题》</td><td>1938.11</td><td>明确&quot;枪杆子里面出政权&quot;；批判右倾投降主义；确立独立自主的山地游击战方针</td></tr><tr><td>《五四运动》</td><td>1939.05</td><td>总结五四运动经验，论述知识青年与工农相结合</td></tr><tr><td>《青年运动的方向》</td><td>1939.05</td><td>青年必须与工农结合；判断革命力量与反革命力量的标准</td></tr><tr><td>《〈共产党人〉发刊词》</td><td>1939.10</td><td>提出党的建设&quot;伟大工程&quot;；总结统一战线、武装斗争、党的建设三大法宝</td></tr><tr><td>《中国革命和中国共产党》</td><td>1939.12</td><td><strong>新民主主义理论框架</strong>。系统阐述中国社会的性质、新民主主义革命的总路线、革命对象、动力、前途</td></tr><tr><td>《新民主主义论》</td><td>1940.01</td><td><strong>新民主主义理论成熟标志</strong>。提出新民主主义革命是无产阶级领导的、人民大众的、反帝反封建的革命；论述政治、经济、文化纲领；驳斥&quot;一次革命论&quot;</td></tr></tbody></table><p><strong>理论贡献</strong></p><ul><li>持久抗战理论</li><li>新民主主义革命理论体系完整形成</li><li>党的建设&quot;伟大工程&quot;</li><li>三大法宝理论（统一战线、武装斗争、党的建设）</li></ul><hr><h3 id="📖-第5卷-1941-1945-延安整风与七大的准备" tabindex="-1">📖 第5卷（1941-1945）：延安整风与七大的准备 <a class="header-anchor" href="#📖-第5卷-1941-1945-延安整风与七大的准备" aria-label="Permalink to &quot;📖 第5卷（1941-1945）：延安整风与七大的准备&quot;">​</a></h3><p><strong>时代背景</strong></p><ul><li>延安整风运动（1942-1945）</li><li>抗日战争最艰难阶段</li><li>大生产运动（三五九旅南泥湾）</li><li>党的七大（1945.04-06）</li></ul><p><strong>核心文章</strong></p><table tabindex="0"><thead><tr><th>文章</th><th>年份</th><th>核心内容</th></tr></thead><tbody><tr><td>《改造我们的学习》</td><td>1941.05</td><td><strong>整风开篇之作</strong>。批判主观主义学风；提出&quot;实事求是&quot;的核心内涵；对理论与实际脱离的学风进行系统批判</td></tr><tr><td>《整顿党的作风》</td><td>1942.02</td><td>反对主观宗派主义；提出&quot;理论联系实际&quot;；批判教条主义和经验主义</td></tr><tr><td>《反对党八股》</td><td>1942.02</td><td>批判文风问题；提出马列主义文风标准</td></tr><tr><td>《在延安文艺座谈会上的讲话》</td><td>1942.05</td><td><strong>文艺理论里程碑</strong>。文艺为工农兵服务；普及与提高；以政治标准放在第一位；文艺工作者必须改造世界观</td></tr><tr><td>《为人民服务》</td><td>1944.09</td><td><strong>群众路线经典</strong>。&quot;为人民利益而死，就比泰山还重&quot;；为人民服务是共产党的根本宗旨</td></tr><tr><td>《愚公移山》</td><td>1945.06</td><td>党的七大作闭幕词；引用寓言比喻；提出&quot;下定决心，不怕牺牲，排除万难&quot;的精神</td></tr></tbody></table><p><strong>整风运动的历史意义</strong></p><ul><li>确立了实事求是的思想路线</li><li>克服了主观主义、教条主义、宗派主义</li><li>统一了全党思想</li><li>为七大召开和解放战争胜利奠定思想基础</li></ul><hr><h3 id="📖-第6卷-1945-1948-解放战争战略进攻" tabindex="-1">📖 第6卷（1945-1948）：解放战争战略进攻 <a class="header-anchor" href="#📖-第6卷-1945-1948-解放战争战略进攻" aria-label="Permalink to &quot;📖 第6卷（1945-1948）：解放战争战略进攻&quot;">​</a></h3><p><strong>时代背景</strong></p><ul><li>抗日战争胜利（1945.08）</li><li>重庆谈判（1945.08-10）</li><li>国民党发动内战（1946.06）</li><li>人民解放军转入战略进攻（1947.06后）</li></ul><p><strong>核心文章</strong></p><table tabindex="0"><thead><tr><th>文章</th><th>年份</th><th>核心内容</th></tr></thead><tbody><tr><td>《关于重庆谈判》</td><td>1945.10</td><td>重庆谈判的策略分析；&quot;针锋相对，寸土必争&quot;；帝国主义和反动派都是纸老虎</td></tr><tr><td>《和美国记者安娜·路易斯·斯特朗的谈话》</td><td>1946.08</td><td><strong>&quot;一切反动派都是纸老虎&quot;论断</strong>。从战略上藐视敌人；原子弹是纸老虎；决定战争胜负的是人民</td></tr><tr><td>《集中优势兵力，各个歼灭敌人》</td><td>1946.09</td><td>军事原则：集中兵力打歼灭战；不计较一城一地得失</td></tr><tr><td>《解放战争第二年的战略方针》</td><td>1947.09</td><td>人民解放军转入战略进攻；以主力打到外线去</td></tr><tr><td>《目前形势和我们的任务》</td><td>1947.12</td><td><strong>解放战争的政治经济军事纲领</strong>。提出十大军事原则；土地改革总路线；没收官僚资本；统一战线</td></tr></tbody></table><p><strong>十大军事原则</strong>（1947年提出）</p><ol><li>先打分散孤立之敌，后打集中强大之敌</li><li>先取中小城市和农村，再取大城市</li><li>歼灭战为主，避免消耗战</li><li>集中绝对优势兵力（四五倍），各个歼灭敌人</li><li>先消灭敌人有生力量，再占领地方</li><li>不打无准备无把握之战</li><li>力求在运动中歼灭敌人</li><li>攻城原则：不惜代价，但避免重大伤亡</li><li>以俘虏敌人补充自己</li><li>继续利用休整时间整训</li></ol><hr><h3 id="📖-第7卷-1948-1949-决战与建国" tabindex="-1">📖 第7卷（1948-1949）：决战与建国 <a class="header-anchor" href="#📖-第7卷-1948-1949-决战与建国" aria-label="Permalink to &quot;📖 第7卷（1948-1949）：决战与建国&quot;">​</a></h3><p><strong>时代背景</strong></p><ul><li>辽沈、淮海、平津三大战役（1948.09-1949.01）</li><li>解放南京（1949.04）</li><li>中华人民共和国成立（1949.10）</li></ul><p><strong>核心文章</strong></p><table tabindex="0"><thead><tr><th>文章</th><th>年份</th><th>核心内容</th></tr></thead><tbody><tr><td>《关于平津战役的作战方针》</td><td>1948.12</td><td>战略决战阶段的指挥艺术；&quot;先打两头，后取中间&quot;</td></tr><tr><td>《把军队变为工作队》</td><td>1949.02</td><td>军队执行工作队任务；接收和管理城市</td></tr><tr><td>《在中国共产党第七届中央委员会第二次全体会议上的报告》</td><td>1949.03</td><td><strong>建国方略总纲</strong>。工作重心从农村转向城市；城市工作以生产建设为中心；新民主主义经济成分分析；警惕资产阶级糖衣炮弹</td></tr><tr><td>《论人民民主专政》</td><td>1949.06</td><td><strong>建国理论奠基</strong>。人民民主专政的内涵；对内外敌人的专政；各阶级在国家中的地位；中国的建国道路</td></tr></tbody></table><p><strong>七届二中全会核心内容</strong></p><ul><li>工作重心转移：乡村→城市</li><li>城市中心任务：生产建设</li><li>新民主主义五种经济成分：国营经济、合作社经济、私人资本主义经济、个体经济、国家资本主义经济</li><li>警惕&quot;糖衣炮弹&quot;：资产阶级腐蚀</li><li>建设先进工业国的总任务</li></ul><hr><h2 id="三、贯穿全书的核心理论体系" tabindex="-1">三、贯穿全书的核心理论体系 <a class="header-anchor" href="#三、贯穿全书的核心理论体系" aria-label="Permalink to &quot;三、贯穿全书的核心理论体系&quot;">​</a></h2><h3 id="_1-哲学思想" tabindex="-1">1. 哲学思想 <a class="header-anchor" href="#_1-哲学思想" aria-label="Permalink to &quot;1. 哲学思想&quot;">​</a></h3><h4 id="认识论-《实践论》《矛盾论》" tabindex="-1">认识论（《实践论》《矛盾论》） <a class="header-anchor" href="#认识论-《实践论》《矛盾论》" aria-label="Permalink to &quot;认识论（《实践论》《矛盾论》）&quot;">​</a></h4><p><strong>认识的总公式：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>实践 → 感性认识 → 理性认识 → 实践</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>    认识的两个阶段       再实践 → 再认识（螺旋上升）</span></span></code></pre></div><p><strong>核心原理：</strong></p><ul><li>实践是认识的基础（&quot;你要知道梨子的滋味，你就得变革梨子，亲口吃一吃&quot;）</li><li>认识依赖于实践</li><li>认识运动是一个不断深化的发展过程</li><li>改造客观世界与改造主观世界的统一</li></ul><p><strong>矛盾法则：</strong></p><ul><li>矛盾的普遍性（无处不在、无时不在）</li><li>矛盾的特殊性（&quot;不同质的矛盾，只有用不同质的方法才能解决&quot;）</li><li>主要矛盾与次要矛盾</li><li>矛盾的主要方面与次要方面</li><li>对抗在矛盾中的地位</li></ul><h4 id="方法论-《反对本本主义》《改造我们的学习》" tabindex="-1">方法论（《反对本本主义》《改造我们的学习》） <a class="header-anchor" href="#方法论-《反对本本主义》《改造我们的学习》" aria-label="Permalink to &quot;方法论（《反对本本主义》《改造我们的学习》）&quot;">​</a></h4><ul><li><strong>没有调查，没有发言权</strong></li><li><strong>实事求是</strong>：&quot;实事&quot;就是客观存在着的一切事物，&quot;是&quot;就是客观事物的内部联系，即规律性，&quot;求&quot;就是我们去研究</li><li>理论联系实际</li><li>具体问题具体分析</li></ul><hr><h3 id="_2-革命理论" tabindex="-1">2. 革命理论 <a class="header-anchor" href="#_2-革命理论" aria-label="Permalink to &quot;2. 革命理论&quot;">​</a></h3><h4 id="新民主主义革命理论" tabindex="-1">新民主主义革命理论 <a class="header-anchor" href="#新民主主义革命理论" aria-label="Permalink to &quot;新民主主义革命理论&quot;">​</a></h4><p><strong>总路线：</strong></p><blockquote><p>无产阶级领导，人民大众的，彻底反帝反封建的革命</p></blockquote><p><strong>革命对象：</strong> 帝国主义、封建主义、官僚资本主义</p><p><strong>革命动力：</strong> 无产阶级、农民阶级、小资产阶级、民族资产阶级</p><p><strong>革命前途：</strong> 新民主主义→社会主义（两步走）</p><p><strong>革命领导权：</strong> 必须由无产阶级（通过共产党）领导，这是革命成败的关键</p><p><strong>基本经验（三大法宝）：</strong></p><ol><li>统一战线（最广泛的政治联盟）</li><li>武装斗争（主要斗争形式）</li><li>党的建设（核心领导力量）</li></ol><hr><h3 id="_3-军事思想" tabindex="-1">3. 军事思想 <a class="header-anchor" href="#_3-军事思想" aria-label="Permalink to &quot;3. 军事思想&quot;">​</a></h3><h4 id="人民战争思想" tabindex="-1">人民战争思想 <a class="header-anchor" href="#人民战争思想" aria-label="Permalink to &quot;人民战争思想&quot;">​</a></h4><ul><li>战争的正义性是胜利的根本</li><li>兵民是胜利之本</li><li>动员群众、依靠群众</li><li>游击战与运动战相结合</li></ul><h4 id="战略战术原则" tabindex="-1">战略战术原则 <a class="header-anchor" href="#战略战术原则" aria-label="Permalink to &quot;战略战术原则&quot;">​</a></h4><ul><li>战略上藐视敌人，战术上重视敌人</li><li>集中优势兵力，各个歼灭敌人</li><li>打得赢就打，打不赢就跑（灵活性）</li><li>诱敌深入</li><li>持久战（对强敌）</li></ul><h4 id="人民军队建设" tabindex="-1">人民军队建设 <a class="header-anchor" href="#人民军队建设" aria-label="Permalink to &quot;人民军队建设&quot;">​</a></h4><ul><li>党指挥枪，而非枪指挥党</li><li>官兵一致、军民一致、瓦解敌军</li><li>政治工作是军队的生命线</li><li>人民军队的三大任务：打仗、生产、做群众工作</li></ul><hr><h3 id="_4-群众路线" tabindex="-1">4. 群众路线 <a class="header-anchor" href="#_4-群众路线" aria-label="Permalink to &quot;4. 群众路线&quot;">​</a></h3><p><strong>经典表述：</strong></p><blockquote><p>&quot;我们共产党人好比种子，人民好比土地。我们到了一个地方，就要同那里的人民结合起来，在人民中间生根、开花。&quot;</p></blockquote><p><strong>群众路线的内涵：</strong></p><ul><li>从群众中来，到群众中去</li><li>一切为了群众，一切依靠群众</li><li>把党的正确主张变为群众的自觉行动</li></ul><p><strong>与实际工作的结合：</strong></p><ul><li>关心群众生活，注意工作方法</li><li>真正的铜墙铁壁是群众</li><li>眼睛向下，不要只是昂首望天</li></ul><hr><h3 id="_5-统一战线理论" tabindex="-1">5. 统一战线理论 <a class="header-anchor" href="#_5-统一战线理论" aria-label="Permalink to &quot;5. 统一战线理论&quot;">​</a></h3><p><strong>基本策略：</strong></p><ul><li>发展进步势力</li><li>争取中间势力</li><li>孤立顽固势力</li></ul><p><strong>对资产阶级的策略：</strong></p><ul><li>又联合又斗争</li><li>以斗争求团结则团结存，以退让求团结则团结亡</li><li>原则性与灵活性相结合</li></ul><p><strong>抗日民族统一战线：</strong></p><ul><li>独立自主（领导权是关键）</li><li>又团结又斗争</li><li>发展进步势力，争取中间势力，孤立顽固势力</li></ul><hr><h3 id="_6-党的建设思想" tabindex="-1">6. 党的建设思想 <a class="header-anchor" href="#_6-党的建设思想" aria-label="Permalink to &quot;6. 党的建设思想&quot;">​</a></h3><h4 id="思想建设-首位" tabindex="-1">思想建设（首位） <a class="header-anchor" href="#思想建设-首位" aria-label="Permalink to &quot;思想建设（首位）&quot;">​</a></h4><ul><li>用马克思主义理论武装全党</li><li>克服党内非无产阶级思想</li><li>实事求是思想路线</li></ul><h4 id="组织建设" tabindex="-1">组织建设 <a class="header-anchor" href="#组织建设" aria-label="Permalink to &quot;组织建设&quot;">​</a></h4><ul><li>民主集中制</li><li>&quot;四个服从&quot;：个人服从组织、少数服从多数、下级服从上级、全党服从中央</li><li>维护党的统一</li></ul><h4 id="作风建设" tabindex="-1">作风建设 <a class="header-anchor" href="#作风建设" aria-label="Permalink to &quot;作风建设&quot;">​</a></h4><ul><li>理论联系实际</li><li>密切联系群众</li><li>批评与自我批评</li></ul><h4 id="整风运动方法" tabindex="-1">整风运动方法 <a class="header-anchor" href="#整风运动方法" aria-label="Permalink to &quot;整风运动方法&quot;">​</a></h4><ul><li>惩前毖后，治病救人</li><li>既要弄清思想，又要团结同志</li><li>学习——对照——批评——总结</li></ul><hr><h3 id="_7-经济思想" tabindex="-1">7. 经济思想 <a class="header-anchor" href="#_7-经济思想" aria-label="Permalink to &quot;7. 经济思想&quot;">​</a></h3><h4 id="根据地经济建设" tabindex="-1">根据地经济建设 <a class="header-anchor" href="#根据地经济建设" aria-label="Permalink to &quot;根据地经济建设&quot;">​</a></h4><ul><li>发展生产，保障供给</li><li>自己动手，丰衣足食（大生产运动）</li><li>公私兼顾、军民兼顾</li></ul><h4 id="新民主主义经济结构" tabindex="-1">新民主主义经济结构 <a class="header-anchor" href="#新民主主义经济结构" aria-label="Permalink to &quot;新民主主义经济结构&quot;">​</a></h4><table tabindex="0"><thead><tr><th>经济成分</th><th>性质</th><th>政策</th></tr></thead><tbody><tr><td>国营经济</td><td>社会主义</td><td>领导地位</td></tr><tr><td>合作社经济</td><td>半社会主义</td><td>鼓励发展</td></tr><tr><td>私人资本主义经济</td><td>资本主义</td><td>鼓励+限制</td></tr><tr><td>个体经济</td><td>小生产者</td><td>保护+引导</td></tr><tr><td>国家资本主义经济</td><td>过渡形式</td><td>有限发展</td></tr></tbody></table><h4 id="没收官僚资本" tabindex="-1">没收官僚资本 <a class="header-anchor" href="#没收官僚资本" aria-label="Permalink to &quot;没收官僚资本&quot;">​</a></h4><ul><li>官僚资本 = 封建性 + 买办性 + 垄断性</li><li>没收官僚资本归人民共和国所有</li><li>这是新民主主义革命的三大经济纲领之一</li></ul><hr><h3 id="_8-政权思想" tabindex="-1">8. 政权思想 <a class="header-anchor" href="#_8-政权思想" aria-label="Permalink to &quot;8. 政权思想&quot;">​</a></h3><h4 id="工农武装割据" tabindex="-1">工农武装割据 <a class="header-anchor" href="#工农武装割据" aria-label="Permalink to &quot;工农武装割据&quot;">​</a></h4><blockquote><p>以武装斗争为主要形式、以土地革命为基本内容、以根据地建设为战略依托</p></blockquote><h4 id="红色政权理论" tabindex="-1">红色政权理论 <a class="header-anchor" href="#红色政权理论" aria-label="Permalink to &quot;红色政权理论&quot;">​</a></h4><p><strong>存在条件：</strong></p><ol><li>中国是一个政治经济发展不平衡的半殖民地半封建大国</li><li>白色政权之间的战争不断</li><li>有相当力量的正式红军存在</li><li>共产党组织的有力量和政策的不错误</li><li>有足够给养的经济力</li></ol><h4 id="人民民主专政" tabindex="-1">人民民主专政 <a class="header-anchor" href="#人民民主专政" aria-label="Permalink to &quot;人民民主专政&quot;">​</a></h4><p><strong>性质：</strong> 以工人阶级为领导、以工农联盟为基础的各革命阶级的联合专政</p><p><strong>对谁专政：</strong> 对地主阶级、官僚资产阶级、帝国主义及其走狗实行专政</p><p><strong>对谁民主：</strong> 工人阶级、农民阶级、城市小资产阶级、民族资产阶级</p><p><strong>历史任务：</strong> 保卫人民民主政权，为建设社会主义创造条件</p><hr><h2 id="四、文集-vs-选集-有什么区别" tabindex="-1">四、文集 vs 选集：有什么区别 <a class="header-anchor" href="#四、文集-vs-选集-有什么区别" aria-label="Permalink to &quot;四、文集 vs 选集：有什么区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比维度</th><th>毛泽东文集</th><th>毛泽东选集</th></tr></thead><tbody><tr><td>收录范围</td><td>1921-1949年全部重要文稿（含指示、命令、批示、电报）</td><td>最具代表性的名篇（经毛泽东审定的&quot;定稿&quot;）</td></tr><tr><td>篇幅</td><td>8卷本，更全面</td><td>4卷本（另有第5卷等），更精炼</td></tr><tr><td>内部文献</td><td>大量收录内部文章、作战命令</td><td>主要收录面向全党全民的正式文章</td></tr><tr><td>修订情况</td><td>部分保留原始面貌</td><td>经毛泽东亲自修订润色</td></tr><tr><td>用途</td><td>研究原始文献、政治军事决策过程</td><td>学习理论体系、掌握思想精髓</td></tr></tbody></table><hr><h2 id="五、经典名篇索引-按主题分类" tabindex="-1">五、经典名篇索引（按主题分类） <a class="header-anchor" href="#五、经典名篇索引-按主题分类" aria-label="Permalink to &quot;五、经典名篇索引（按主题分类）&quot;">​</a></h2><h3 id="哲学入门必读" tabindex="-1">哲学入门必读 <a class="header-anchor" href="#哲学入门必读" aria-label="Permalink to &quot;哲学入门必读&quot;">​</a></h3><ol><li>《实践论》——认识论</li><li>《矛盾论》——辩证法</li><li>《反对本本主义》——思想路线</li><li>《改造我们的学习》——学风</li></ol><h3 id="革命战略必读" tabindex="-1">革命战略必读 <a class="header-anchor" href="#革命战略必读" aria-label="Permalink to &quot;革命战略必读&quot;">​</a></h3><ol><li>《中国的红色政权为什么能够存在？》——根据地理论</li><li>《星星之火，可以燎原》——战略预见</li><li>《论持久战》——抗战方略</li><li>《中国革命和中国共产党》——革命总路线</li><li>《新民主主义论》——理论成熟标志</li></ol><h3 id="军事思想必读" tabindex="-1">军事思想必读 <a class="header-anchor" href="#军事思想必读" aria-label="Permalink to &quot;军事思想必读&quot;">​</a></h3><ol><li>《中国革命战争的战略问题》——军事理论奠基</li><li>《论持久战》——人民战争</li><li>《集中优势兵力，各个歼灭敌人》——战术原则</li><li>十大军事原则（见文集第6卷）</li></ol><h3 id="群众路线必读" tabindex="-1">群众路线必读 <a class="header-anchor" href="#群众路线必读" aria-label="Permalink to &quot;群众路线必读&quot;">​</a></h3><ol><li>《关心群众生活，注意工作方法》</li><li>《为人民服务》</li><li>《愚公移山》</li><li>《在延安文艺座谈会上的讲话》</li></ol><h3 id="党的建设必读" tabindex="-1">党的建设必读 <a class="header-anchor" href="#党的建设必读" aria-label="Permalink to &quot;党的建设必读&quot;">​</a></h3><ol><li>《〈共产党人〉发刊词》——三大法宝</li><li>《反对自由主义》——思想作风</li><li>《整顿党的作风》——整风文献</li><li>《党委会的工作方法》——领导艺术</li></ol><h3 id="建国方略必读" tabindex="-1">建国方略必读 <a class="header-anchor" href="#建国方略必读" aria-label="Permalink to &quot;建国方略必读&quot;">​</a></h3><ol><li>《在中国共产党第七届中央委员会第二次全体会议上的报告》——工作重心转移</li><li>《论人民民主专政》——国家政权理论</li></ol><hr><h2 id="六、核心方法论总结" tabindex="-1">六、核心方法论总结 <a class="header-anchor" href="#六、核心方法论总结" aria-label="Permalink to &quot;六、核心方法论总结&quot;">​</a></h2><h3 id="解决问题的方法论框架" tabindex="-1">解决问题的方法论框架 <a class="header-anchor" href="#解决问题的方法论框架" aria-label="Permalink to &quot;解决问题的方法论框架&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 调查研究（一切决策的基础）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>2. 矛盾分析（抓住主要矛盾）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>3. 实事求是（从实际出发）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>4. 群众路线（从群众中来，到群众中去）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>5. 实践检验（实践是检验真理的唯一标准）</span></span></code></pre></div><h3 id="战略分析框架" tabindex="-1">战略分析框架 <a class="header-anchor" href="#战略分析框架" aria-label="Permalink to &quot;战略分析框架&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 敌我力量对比（敌强我弱时：持久战、游击战）</span></span>
<span class="line"><span>2. 主次矛盾判断（主要矛盾决定战略重心）</span></span>
<span class="line"><span>3. 发展阶段划分（量变质变规律）</span></span>
<span class="line"><span>4. 战略与战术统一（宏观与微观协调）</span></span></code></pre></div><h3 id="领导方法论" tabindex="-1">领导方法论 <a class="header-anchor" href="#领导方法论" aria-label="Permalink to &quot;领导方法论&quot;">​</a></h3><ul><li>&quot;牵牛鼻子&quot;——抓主要矛盾</li><li>&quot;弹钢琴&quot;——统筹兼顾</li><li>&quot;解剖麻雀&quot;——典型调查</li><li>&quot;到什么山唱什么歌&quot;——具体问题具体分析</li></ul><hr><h2 id="七、文集中的经典语录摘编" tabindex="-1">七、文集中的经典语录摘编 <a class="header-anchor" href="#七、文集中的经典语录摘编" aria-label="Permalink to &quot;七、文集中的经典语录摘编&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语录</th><th>出处</th></tr></thead><tbody><tr><td>&quot;谁是我们的敌人，谁是我们的朋友，这个问题是革命的首要问题。&quot;</td><td>《中国社会各阶级的分析》1925</td></tr><tr><td>&quot;枪杆子里面出政权。&quot;</td><td>八七会议 1927.08</td></tr><tr><td>&quot;星星之火，可以燎原。&quot;</td><td>《星星之火，可以燎原》1930.01</td></tr><tr><td>&quot;没有调查，没有发言权。&quot;</td><td>《反对本本主义》1930.05</td></tr><tr><td>&quot;战略上藐视敌人，战术上重视敌人。&quot;</td><td>《中国革命战争的战略问题》1936.12</td></tr><tr><td>&quot;实践、认识、再实践、再认识，这种形式，循环往复以至无穷。&quot;</td><td>《实践论》1937.07</td></tr><tr><td>&quot;外因是变化的条件，内因是变化的根据，外因通过内因而起作用。&quot;</td><td>《矛盾论》1937.08</td></tr><tr><td>&quot;武器是战争的重要的因素，但不是决定的因素，决定的因素是人不是物。&quot;</td><td>《论持久战》1938.05</td></tr><tr><td>&quot;统一战线、武装斗争、党的建设，是中国共产党在中国革命中战胜敌人的三个法宝。&quot;</td><td>《〈共产党人〉发刊词》1939.10</td></tr><tr><td>&quot;实事求是的态度，就是理论和实际相统一的态度。&quot;</td><td>《改造我们的学习》1941.05</td></tr><tr><td>&quot;为人民利益而死，就比泰山还重。&quot;</td><td>《为人民服务》1944.09</td></tr><tr><td>&quot;一切反动派都是纸老虎。&quot;</td><td>和斯特朗谈话 1946.08</td></tr><tr><td>&quot;下定决心，不怕牺牲，排除万难，去争取胜利。&quot;</td><td>《愚公移山》1945.06</td></tr><tr><td>&quot;我们不但善于破坏一个旧世界，我们还将善于建设一个新世界。&quot;</td><td>七届二中全会报告 1949.03</td></tr><tr><td>&quot;让哲学从哲学家的课堂上和书本里解放出来。&quot;</td><td>《实践论》《矛盾论》发表时语</td></tr></tbody></table><hr><h2 id="八、学习建议" tabindex="-1">八、学习建议 <a class="header-anchor" href="#八、学习建议" aria-label="Permalink to &quot;八、学习建议&quot;">​</a></h2><h3 id="不同目的的阅读路线" tabindex="-1">不同目的的阅读路线 <a class="header-anchor" href="#不同目的的阅读路线" aria-label="Permalink to &quot;不同目的的阅读路线&quot;">​</a></h3><p><strong>想系统掌握理论体系：</strong></p><blockquote><p>第3卷（《实践论》《矛盾论》《论反对日本帝国主义的策略》）→ 第4卷（《新民主主义论》《中国革命和中国共产党》）→ 第7卷（七届二中全会报告、《论人民民主专政》）</p></blockquote><p><strong>想理解中国革命战略：</strong></p><blockquote><p>第2卷（《星星之火，可以燎原》《反对本本主义》）→ 第3卷（《论持久战》）→ 第6卷（《目前形势和我们的任务》、十大军事原则）</p></blockquote><p><strong>想学领导方法和思维：</strong></p><blockquote><p>第5卷整风文献（《改造我们的学习》《整顿党的作风》）→ 第7卷（《党委会的工作方法》）</p></blockquote><p><strong>想了解具体历史决策：</strong></p><blockquote><p>直接按卷次阅读（文集保留了更多原始电报、命令、批示）</p></blockquote><hr><h2 id="九、相关知识库文件" tabindex="-1">九、相关知识库文件 <a class="header-anchor" href="#九、相关知识库文件" aria-label="Permalink to &quot;九、相关知识库文件&quot;">​</a></h2><ul><li>topics/intellectual-self-learning/ — 包含学习方法论参考</li><li>topics/career-observation/ — 包含领导艺术参考</li><li>topics/wind-energy/ — 风电行业应用（矛盾分析法在产业分析中的运用）</li></ul><hr><p><em>最后更新：2026-06-16</em><em>整理说明：本文件为知识性整理，内容基于人民出版社《毛泽东文集》（8卷本）公开出版文献。不涉及对任何历史人物或历史事件的评价，仅供学习参考。</em></p>`,187)])])}const b=l(r,[["render",o]]);export{p as __pageData,b as default};
